using System;using System.Data;using System.Data.SqlClient;namespace HRM.DAL{public class HRMDAL{public DataTable Query(string sql,params SqlParameter[] p){using(var c=Db.Open())using(var a=new SqlDataAdapter(sql,c)){if(p!=null)a.SelectCommand.Parameters.AddRange(p);var t=new DataTable();a.Fill(t);return t;}}public int Exec(string sql,params SqlParameter[] p){using(var c=Db.Open())using(var x=new SqlCommand(sql,c)){if(p!=null)x.Parameters.AddRange(p);return x.ExecuteNonQuery();}}
 public DataTable GetAttendance(string month){using(var c=Db.Open()){using(var seed=new SqlCommand("INSERT BangChamCong(MaNV,ThangNam,SoNgayCong,SoGioOT) SELECT n.MaNV,@m,0,0 FROM NhanVien n WHERE NOT EXISTS(SELECT 1 FROM BangChamCong b WHERE b.MaNV=n.MaNV AND b.ThangNam=@m) AND NOT EXISTS(SELECT 1 FROM BangLuong l WHERE l.MaNV=n.MaNV AND l.ThangNam=@m)",c)){seed.Parameters.Add("@m",SqlDbType.VarChar,7).Value=month;seed.ExecuteNonQuery();}var a=new SqlDataAdapter("SELECT MaCong,MaNV,ThangNam,SoNgayCong,SoGioOT FROM BangChamCong WHERE ThangNam=@m ORDER BY MaNV",c);a.MissingSchemaAction=MissingSchemaAction.AddWithKey;a.SelectCommand.Parameters.Add("@m",SqlDbType.VarChar,7).Value=month;var t=new DataTable();a.Fill(t);return t;}}
 public void SaveAttendance(DataTable t){using(var c=Db.Open()){string m=t.Rows.Count==0?"":Convert.ToString(t.Rows[0]["ThangNam"]);using(var check=new SqlCommand("SELECT COUNT(*) FROM BangLuong WHERE ThangNam=@m",c)){check.Parameters.Add("@m",SqlDbType.VarChar,7).Value=m;if(Convert.ToInt32(check.ExecuteScalar())>0)throw new Exception("Tháng này đã chốt lương, không thể sửa chấm công.");}using(var a=new SqlDataAdapter("SELECT MaCong,MaNV,ThangNam,SoNgayCong,SoGioOT FROM BangChamCong WHERE ThangNam=@m",c)){a.MissingSchemaAction=MissingSchemaAction.AddWithKey;a.SelectCommand.Parameters.Add("@m",SqlDbType.VarChar,7).Value=m;using(var b=new SqlCommandBuilder(a)){b.ConflictOption=ConflictOption.OverwriteChanges;a.Update(t);}}}}
 public void ClosePayroll(string month){using(var c=Db.Open())using(var tr=c.BeginTransaction()){try{using(var check=new SqlCommand("SELECT COUNT(*) FROM BangLuong WHERE ThangNam=@m",c,tr)){check.Parameters.Add("@m",SqlDbType.VarChar,7).Value=month;if(Convert.ToInt32(check.ExecuteScalar())>0)throw new Exception("Tháng này đã được chốt lương.");}string sql="INSERT BangLuong(MaNV,ThangNam,ThucLinh) SELECT n.MaNV,@m,CAST(((n.LuongCoBan*n.HeSoLuong/22.0)*b.SoNgayCong)+(b.SoGioOT*50000) AS DECIMAL(18,2)) FROM NhanVien n JOIN BangChamCong b ON n.MaNV=b.MaNV WHERE b.ThangNam=@m";using(var cmd=new SqlCommand(sql,c,tr)){cmd.Parameters.Add("@m",SqlDbType.VarChar,7).Value=month;int count=cmd.ExecuteNonQuery();if(count==0)throw new Exception("Không có dữ liệu chấm công để chốt lương.");}tr.Commit();}catch{tr.Rollback();throw;}}}
}